import pandas as pd
import numpy as np
from pandas.arrays import SparseArray

# Test 1: empty SparseArray.density
try:
    arr = SparseArray(np.array([], dtype='float64'))
    result = arr.density
    probe('empty_sparse_array_density', float(result) if not np.isnan(result) else np.nan)
except ZeroDivisionError as e:
    probe('empty_sparse_array_density', 'ZeroDivisionError')
except Exception as e:
    probe('empty_sparse_array_density', f'Exception: {type(e).__name__}')

# Test 2: Series.sparse.density with empty SparseArray
try:
    ser = pd.Series(SparseArray(np.array([], dtype='float64')))
    result = ser.sparse.density
    probe('series_sparse_density', float(result) if not np.isnan(result) else np.nan)
except ZeroDivisionError as e:
    probe('series_sparse_density', 'ZeroDivisionError')
except Exception as e:
    probe('series_sparse_density', f'Exception: {type(e).__name__}')

# Test 3: DataFrame.sparse.density with empty SparseArray
try:
    df = pd.DataFrame({'A': SparseArray(np.array([], dtype='float64'))})
    result = df.sparse.density
    probe('dataframe_sparse_density', float(result) if not np.isnan(result) else np.nan)
except ZeroDivisionError as e:
    probe('dataframe_sparse_density', 'ZeroDivisionError')
except Exception as e:
    probe('dataframe_sparse_density', f'Exception: {type(e).__name__}')

